const places = [
{"id": "paleocristiano", "label": "Paleocristiano", "culture": "ARQUITECTURA PALEOCRISTIANA", "name": "San Pedro", "country": "VATICANO", "period": "Siglo IV", "lat": 41.9022, "lon": 12.4539, "coords": "41.9022° N / 12.4539° E", "headline": "La basílica como lugar de encuentro.", "text": "La antigua basílica de San Pedro, impulsada por Constantino en el siglo IV, es un referente de la arquitectura paleocristiana. Su organización longitudinal, con cinco naves, atrio y ábside, orientaba a la comunidad hacia el altar y la memoria del apóstol.", "detail": "El edificio original no se conserva en pie. Fue sustituido por la basílica actual, cuya construcción comenzó en 1506 y concluyó en 1626. La comparación muestra dos edificios distintos en el mismo lugar.", "fact": "Planta basilical y cinco naves", "main": "paleo-historico", "second": "paleo-actual", "caption": "Antigua San Pedro · reconstrucción gráfica de H. W. Brewer, 1891. Representa su aspecto tardomedieval, con modificaciones posteriores al siglo IV.", "caption2": "Basílica actual de San Pedro · fotografía de 2019. Sustituyó al edificio paleocristiano; no es su estado original restaurado.", "status": "EDIFICIO ORIGINAL REEMPLAZADO", "source": "https://www.basilicasanpietro.va/en/faq/when-was-st-peters-basilica-built", "sourceName": "Basílica de San Pedro", "history": true},
{"id": "bizantino", "label": "Bizantino", "culture": "IMPERIO BIZANTINO", "name": "Santa Sofía", "country": "TURQUÍA", "period": "532–537 d. C.", "lat": 41.0086, "lon": 28.9802, "coords": "41.0086° N / 28.9802° E", "headline": "Una cúpula que transforma el espacio.", "text": "Construida en Constantinopla bajo Justiniano, Santa Sofía es una obra emblemática del mundo bizantino. Antemio de Trales e Isidoro de Mileto combinaron una gran cúpula sobre pechinas con semicúpulas y un interior monumental atravesado por la luz.", "detail": "El edificio se conserva en Estambul, con reparaciones y añadidos de distintas épocas. Los minaretes pertenecen a su transformación otomana. La ilustración histórica es de 1857: documenta esa etapa posterior y no reconstruye el templo del siglo VI.", "fact": "Cúpula sobre pechinas", "main": "bizantino-historico", "second": "bizantino-actual", "caption": "Santa Sofía · ilustración de 1857, ya en época otomana. No representa su aspecto bizantino original.", "caption2": "Santa Sofía en Estambul · fotografía de enero de 2023. Se conservan la estructura histórica y añadidos de épocas posteriores.", "status": "EDIFICIO CONSERVADO Y TRANSFORMADO", "source": "https://whc.unesco.org/en/list/356/", "sourceName": "UNESCO", "history": true},
{"id": "carolingio", "label": "Carolingio", "culture": "IMPERIO CAROLINGIO", "name": "Aquisgrán", "country": "ALEMANIA", "period": "Finales del siglo VIII–inicios del IX", "lat": 50.7747, "lon": 6.0839, "coords": "50.7747° N / 6.0839° E", "headline": "Una capilla para el poder imperial.", "text": "La Capilla Palatina de Carlomagno es el núcleo de la catedral de Aquisgrán. Su espacio central octogonal, rodeado por un deambulatorio y tribunas, retoma modelos de la Antigüedad y del mundo bizantino para expresar el proyecto imperial carolingio.", "detail": "El núcleo carolingio se conserva, integrado en una catedral ampliada durante siglos. La lámina histórica permite comparar plantas y secciones del conjunto; la fotografía muestra su exterior con transformaciones posteriores, que no deben atribuirse todas a Carlomagno.", "fact": "Octógono central y tribunas", "main": "carolingio-historico", "second": "carolingio-actual", "caption": "Catedral de Aquisgrán · plantas y secciones de Georg Dehio y Gustav von Bezold (1887–1901). Incluye el núcleo carolingio y ampliaciones posteriores.", "caption2": "Capilla Palatina integrada en la catedral de Aquisgrán · fotografía de 2009. El núcleo octogonal sobrevive con añadidos posteriores.", "status": "NÚCLEO CAROLINGIO CONSERVADO", "source": "https://whc.unesco.org/en/list/3/", "sourceName": "UNESCO", "history": true},
 {id:'inca',culture:'IMPERIO INCA',name:'Machu Picchu',country:'PERÚ',period:'Siglo XV',lat:-13.1631,lon:-72.545,coords:'13.1631° S / 72.5450° O',headline:'La montaña como arquitectura.',text:'En lo alto de los Andes, Machu Picchu transforma una pendiente en un lugar para habitar. Terrazas, escaleras y recintos de piedra se adaptan al relieve: la ciudad parece continuar la montaña.',detail:'Su arquitectura une el trabajo de la piedra con el manejo del agua y el paisaje. Los espacios agrícolas y ceremoniales forman parte de un mismo conjunto.',fact:'Piedra y terrazas',main:'inca-machu-picchu',second:'inca-sacred-valley',caption:'Machu Picchu y la montaña Huayna Picchu',caption2:'El conjunto arqueológico y su paisaje andino',source:'https://whc.unesco.org/en/list/274/',sourceName:'UNESCO'},
 {id:'muisca',culture:'CULTURA MUISCA',name:'Guatavita',country:'COLOMBIA',period:'Época prehispánica',lat:4.977,lon:-73.775,coords:'4.9770° N / 73.7750° O',headline:'Un territorio tejido de agua y memoria.',text:'Para los muiscas del altiplano cundiboyacense, las lagunas eran lugares sagrados. Guatavita conserva la memoria de las ofrendas y de una relación con el paisaje que iba más allá de lo material.',detail:'La balsa muisca representa una ceremonia de ofrenda asociada al relato de El Dorado. Fue hallada en Pasca, no en esta laguna, y hoy se conserva en el Museo del Oro de Bogotá.',fact:'Paisaje sagrado',main:'muisca-raft',second:'muisca-guatavita',caption:'Balsa muisca · Museo del Oro, Bogotá',caption2:'Laguna de Guatavita · Sesquilé, Cundinamarca',source:'https://enciclopedia.banrepcultural.org/Balsa_muisca',sourceName:'Banco de la República'},
 {id:'roma',culture:'CIVILIZACIÓN ROMANA',name:'Roma',country:'ITALIA',period:'Antigüedad romana',lat:41.8902,lon:12.4922,coords:'41.8902° N / 12.4922° E',headline:'Construir la vida en común.',text:'En Roma, la arquitectura convirtió la ciudad en un escenario de vida pública. El Coliseo, los foros y los templos muestran distintas formas de reunir a una sociedad y expresar su poder.',detail:'El arco, la bóveda y la cúpula ampliaron las posibilidades del espacio. El Panteón conserva una de las expresiones más reconocibles de esa búsqueda: un gran interior organizado bajo una cúpula.',fact:'Arco, bóveda y cúpula',main:'rome-colosseum',second:'rome-pantheon',caption:'Coliseo · el anfiteatro de la ciudad antigua',caption2:'Panteón · el pórtico y la ciudad',source:'https://whc.unesco.org/en/list/91/',sourceName:'UNESCO'},
 {id:'egipto',culture:'ANTIGUO EGIPTO',name:'Guiza',country:'EGIPTO',period:'III milenio a. C.',lat:29.9792,lon:31.1342,coords:'29.9792° N / 31.1342° E',headline:'La piedra frente al tiempo.',text:'En el borde del desierto, las pirámides de Guiza hacen visible la escala del poder faraónico. Forman parte de complejos funerarios donde la arquitectura articulaba la memoria del gobernante y las creencias sobre la vida después de la muerte.',detail:'Las pirámides, los templos y la Gran Esfinge pertenecen a un paisaje monumental. Su permanencia permite reconocer una manera de construir vinculada con el territorio y lo sagrado.',fact:'Conjunto funerario',main:'egypt-pyramids',second:'egypt-sphinx',caption:'Las pirámides de Guiza y el horizonte del desierto',caption2:'La Gran Esfinge y la pirámide de Keops',source:'https://whc.unesco.org/en/list/86/',sourceName:'UNESCO'}
];
const $=s=>document.querySelector(s);
const project=([lon,lat])=>[(lon+180)/360*1000,(90-lat)/180*500];
const image=(id,alt,main=false)=>`<img src="assets/${id}.jpg" alt="${alt}" loading="lazy" decoding="async" width="${main?1200:600}" height="${main?1000:400}">`;
$('#destination-nav').innerHTML=places.map((p,i)=>`<a class="chapter-tab" href="#${p.id}" data-destination="${p.id}"><span>0${i+1}</span><strong>${p.label || ({inca:'Incas',muisca:'Muiscas',roma:'Roma',egipto:'Egipto'})[p.id]}</strong><i>↗</i></a>`).join('');
$('#markers').innerHTML=places.map((p,i)=>{const[x,y]=project([p.lon,p.lat]);return `<button class="marker" data-id="${p.id}" style="left:${x/10}%;top:${y/5}%" aria-label="Viajar a ${p.name}, ${p.culture.toLowerCase()}"><span class="pin"></span><span class="marker-text"><small>0${i+1} / ${p.country}</small><strong>${p.name}</strong><b>${p.culture.toLowerCase()}</b></span></button>`}).join('');
const historicalChapter=(p,i)=>`<section id="${p.id}" class="chapter historical-chapter" aria-labelledby="title-${p.id}"><div class="chapter-heading"><span class="chapter-number">0${i+1}</span><div><p class="eyebrow">${p.country} / ${p.culture}</p><h2 id="title-${p.id}" tabindex="-1">${p.name}</h2></div><span class="coordinates">${p.coords}<br>${p.period}</span></div><div class="comparison"><figure><div class="image-label">01 / DOCUMENTO HISTÓRICO</div>${image(p.main,p.caption,true)}<figcaption>${p.caption}</figcaption></figure><figure><div class="image-label">02 / EL LUGAR HOY</div>${image(p.second,p.caption2,true)}<figcaption>${p.caption2}</figcaption></figure></div><div class="historical-copy"><div><h3>${p.headline}</h3><span class="conservation">${p.status}</span></div><div><p>${p.text}</p><p>${p.detail}</p><a class="source-link" href="${p.source}" target="_blank" rel="noopener">Leer más · ${p.sourceName} ↗</a></div></div><div class="chapter-next"><a href="#mapa">↖ Volver al mapa</a><a href="#${places[i+1].id}"><span>SIGUIENTE DESTINO</span> ${places[i+1].name} →</a></div></section>`;
$('#chapters').innerHTML=places.map((p,i)=>p.history?historicalChapter(p,i):`<section id="${p.id}" class="chapter" aria-labelledby="title-${p.id}"><div class="chapter-heading"><span class="chapter-number">0${i+1}</span><div><p class="eyebrow">${p.country} / ${p.culture}</p><h2 id="title-${p.id}" tabindex="-1">${p.name}</h2></div><span class="coordinates">${p.coords}<br>${p.period}</span></div><div class="chapter-body"><figure class="photo-main">${image(p.main,p.caption,true)}<figcaption><span>${p.caption}</span><span>01 / 02</span></figcaption></figure><div class="chapter-copy"><h3>${p.headline}</h3><p>${p.text}</p><p>${p.detail}</p><div class="facts"><div><span>HORIZONTE CULTURAL</span><strong>${p.culture.toLowerCase()}</strong></div><div><span>PARA OBSERVAR</span><strong>${p.fact}</strong></div></div><figure class="photo-secondary">${image(p.second,p.caption2)}<figcaption><span>${p.caption2}</span><span>02 / 02</span></figcaption></figure><a class="source-link" href="${p.source}" target="_blank" rel="noopener">Leer más · ${p.sourceName} ↗</a></div></div><div class="chapter-next"><a href="#mapa">↖ Volver al mapa</a><a href="#${places[i+1]?.id||'mapa'}"><span>${i===places.length-1?'FIN DEL RECORRIDO':'SIGUIENTE DESTINO'}</span> ${places[i+1]?.name||'El mundo'} →</a></div></section>`).join('');
for(let lon=-180;lon<=180;lon+=30){const[x]=project([lon,0]);$('#grid').insertAdjacentHTML('beforeend',`<path class="graticule" d="M${x} 0V500"/>`)}
for(let lat=-60;lat<=60;lat+=30){const[,y]=project([0,lat]);$('#grid').insertAdjacentHTML('beforeend',`<path class="graticule" d="M0 ${y}H1000"/>`)}
fetch('assets/land.geojson').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{const polygons=data.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates);$('#land').innerHTML=polygons.map(p=>`<path d="${p.map(r=>r.map((c,i)=>`${i?'L':'M'}${project(c).map(n=>n.toFixed(2)).join(',')}`).join('')+'Z').join('')}"/>`).join('')}).catch(()=>$('#map-error').hidden=false);
fetch('assets/credits.json').then(r=>r.json()).then(items=>{$('#credits').insertAdjacentHTML('beforeend',items.map(p=>`<p><a href="${p.source}" target="_blank" rel="noopener">${p.id}</a> · ${p.credit} · <a href="${p.license_url}" target="_blank" rel="noopener">${p.license}</a>. Imagen redimensionada; encuadre adaptado a la página.</p>`).join(''))});
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let map=null, mapReady=false, pendingArrival=null;
function go(p){document.getElementById(p.id).scrollIntoView({behavior:'instant',block:'start'});history.replaceState(null,'',`#${p.id}`);$(`#title-${p.id}`).focus({preventScroll:true})}
function cancelFlight(){const wasFlying=Boolean(pendingArrival);if(wasFlying&&map)map.off('moveend',pendingArrival);pendingArrival=null;$('#flight-status').hidden=true;if(wasFlying&&map)map.stop()}
function travel(p){cancelFlight();if(!mapReady||reduced()){go(p);return}map.stop();$('#flight-status strong').textContent=p.name;$('#flight-status').hidden=false;$('#mapa').classList.add('exploring');pendingArrival=()=>{pendingArrival=null;$('#flight-status').hidden=true;go(p)};map.once('moveend',pendingArrival);map.flyTo({center:[p.lon,p.lat],zoom:15,pitch:35,bearing:0,duration:2400,essential:false})}
document.querySelectorAll('.marker').forEach(b=>b.addEventListener('click',()=>travel(places.find(p=>p.id===b.dataset.id))));
$('#cancel-flight').addEventListener('click',cancelFlight);
window.addEventListener('keydown',e=>{if(e.key==='Escape')cancelFlight()});
function mapFailure(){mapReady=false;$('#map-status').hidden=false;$('#live-map').hidden=true;$('.map-tools').hidden=true;$('#mapa').classList.remove('live-ready');$('#map-status').textContent='No se pudo cargar el mapa navegable. Puedes usar los destinos del mapa y seguir el recorrido.';cancelFlight()}
async function initMap(){
 try{
  if(!window.maplibregl)throw new Error('MapLibre no disponible');
  const initialZoom=()=>innerWidth<600?0.65:innerWidth<1000?1.2:1.8;
  map=new maplibregl.Map({container:'live-map',locale:{'NavigationControl.ZoomIn':'Acercar','NavigationControl.ZoomOut':'Alejar','NavigationControl.ResetBearing':'Orientar al norte','AttributionControl.ToggleAttribution':'Créditos del mapa'},style:'assets/map-style.json?v=3',center:[-25,22],zoom:initialZoom(),minZoom:0.5,maxZoom:18,renderWorldCopies:false,attributionControl:false,canvasContextAttributes:{antialias:true}});
  // Mayor respuesta para rueda y trackpad, conservando la animación suave.
  map.scrollZoom.setWheelZoomRate(1 / 200);
  map.scrollZoom.setZoomRate(1 / 50);
  map.addControl(new maplibregl.NavigationControl({showCompass:true}),'top-right');
  map.addControl(new maplibregl.AttributionControl({compact:true}),'bottom-right');
  map.addControl(new maplibregl.ScaleControl({unit:'metric'}),'bottom-left');
  map.getCanvas().setAttribute('aria-label','Mapa del mundo. Usa las flechas para desplazarte y más o menos para cambiar el zoom.');
  const offsets={paleocristiano:[-115,25],bizantino:[30,-55],carolingio:[-105,-65],roma:[-70,85],egipto:[40,40],inca:[10,30],muisca:[-100,-40]};
  const anchors=[];
  places.forEach((p,i)=>{
   const el=document.createElement('div');el.className='geo-anchor';
   const button=document.createElement('button');button.type='button';button.className='geo-destination';button.dataset.id=p.id;button.setAttribute('aria-label',`Viajar a ${p.name}, ${p.culture.toLowerCase()}`);button.innerHTML=`<span class="geo-point" aria-hidden="true"></span><span class="geo-label"><small>0${i+1}</small> ${p.name}</span>`;
   button.addEventListener('click',e=>{e.stopPropagation();travel(p)});el.append(button);
   new maplibregl.Marker({element:el,anchor:'center'}).setLngLat([p.lon,p.lat]).addTo(map);anchors.push({el,button,p,offset:offsets[p.id]});
  });
  function markerLayout(){
   const width=map.getContainer().clientWidth,height=map.getContainer().clientHeight;
   for(const {el,button,p,offset} of anchors){
    const point=map.project([p.lon,p.lat]);const close=map.getZoom()>9;
    el.style.visibility=point.x<0||point.x>width||point.y<0||point.y>height?'hidden':'visible';
    const box=button.getBoundingClientRect();
    const x=Math.max(8,Math.min(width-box.width-8,point.x+(close?12:offset[0])));
    const y=Math.max(8,Math.min(height-box.height-35,point.y+(close?-20:offset[1])));
    el.style.setProperty('--dx',`${x-point.x}px`);el.style.setProperty('--dy',`${y-point.y}px`);
   }
  }
  markerLayout();map.on('move',markerLayout);map.on('resize',markerLayout);
  const loadingDeadline=setTimeout(()=>{if(!mapReady)mapFailure()},20000);
  map.on('load',()=>{clearTimeout(loadingDeadline);mapReady=true;$('#live-map').hidden=false;$('#mapa').classList.add('live-ready');$('.map-tools').hidden=false;$('#map-status').hidden=true;map.resize()});
  map.on('error',()=>{if(mapReady){$('#map-status').hidden=false;$('#map-status').textContent='No se pudo cargar parte del mapa. Revisa tu conexión; el recorrido sigue disponible.'}});
  map.on('idle',()=>{if(mapReady&&map.areTilesLoaded())$('#map-status').hidden=true});
  map.on('movestart',e=>{if(e.originalEvent){cancelFlight();$('#mapa').classList.add('exploring')}});
  for(const event of ['wheel','pointerdown','touchstart'])map.getCanvas().addEventListener(event,()=>{cancelFlight();$('#mapa').classList.add('exploring')},{passive:true});
  $('#world-reset').addEventListener('click',()=>{cancelFlight();$('#mapa').classList.remove('exploring');map.flyTo({center:[-25,22],zoom:initialZoom(),pitch:0,bearing:0,duration:reduced()?0:1200})});
  document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',cancelFlight));
 }catch(error){mapFailure()}
}
initMap();
let queued=false;function update(){queued=false;const y=scrollY+innerHeight*.35;let current=null;for(const p of places){if(document.getElementById(p.id).offsetTop<=y)current=p.id}document.querySelectorAll('.chapter-tab').forEach(a=>{const on=a.dataset.destination===current;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});$('.progress').style.width=`${scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100}%`}
window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});update();
if(places.some(p=>`#${p.id}`===location.hash))requestAnimationFrame(()=>document.querySelector(location.hash).scrollIntoView({behavior:'instant'}));
if('IntersectionObserver' in window&&!reduced()){
 const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{threshold:0.08});
 document.querySelectorAll('.photo-main,.chapter-copy,.comparison figure,.historical-copy').forEach(el=>{el.classList.add('reveal');revealObserver.observe(el)});
}
